package dpos

import (
	"encoding/hex"
	"testing"

	"github.com/Vcity-Team/vcitychain/types"
	"github.com/stretchr/testify/require"
)

func Test_displayHeaderHash_block15400000(t *testing.T) {
	extraHex := ""
	extra, err := hex.DecodeString(extraHex)
	require.NoError(t, err)

	header := &types.Header{
		ParentHash:   types.StringToHash("0x7654bdaf04738671e1884e700d9298edc0f30019891bff0628b0ae3d995f32a5"),
		Sha3Uncles:   types.EmptyUncleHash,
		Miner:        types.ZeroAddress.Bytes(),
		StateRoot:    types.StringToHash("0x101f9a8535c88a61d018710771eeb4a944e6c5340af3cf447ce4baa6bd990043"),
		TxRoot:       types.EmptyRootHash,
		ReceiptsRoot: types.EmptyRootHash,
		Difficulty:   15400000,
		Number:       15400000,
		GasLimit:     60000000,
		GasUsed:      0,
		Timestamp:    0x69e58ad2,
		ExtraData:    extra,
		MixHash:      types.StringToHash("0x63746963616c2062797a616e74696e65206661756c7420746f6c6572616e6365"),
	}

	hash := DisplayHeaderHash(header)
	require.NotEqual(t, types.ZeroHash, hash)
	require.Equal(t, types.StringToHash("0x4dc81bf54e4238e5eecf100e2aa55d10ea6f2470ac7964959566acc30acedb31"), hash)
}
